from thirdparty.errors import RecipeException

_DIRTY_FOLDER = ".dirty"
GENERATED_FILE_COMMENT = "This file was generated by Recipe"


def set_dirty(folder: str):
    dirty_file = os.path.normpath(folder) + _DIRTY_FOLDER
    assert not os.path.exists(dirty_file), f"Folder '{folder}' is already dirty"
    save(dirty_file, "")


def clean_dirty(folder: str):
    dirty_file = os.path.normpath(folder) + _DIRTY_FOLDER
    os.remove(dirty_file)


def is_dirty(folder: str) -> bool:
    dirty_file = os.path.normpath(folder) + _DIRTY_FOLDER
    return os.path.exists(dirty_file)


def remove_if_dirty(item: str) -> bool:
    # TODO: Apply to other places this pattern is common
    if is_dirty(item):
        if os.path.exists(item):
            # To avoid circular import in recipe_server
            from thirdparty._internal.output import Output
            Output().warning(f"{item} is dirty, removing it")
            if os.path.isfile(item):
                os.remove(item)
            else:
                rmdir(item)
        clean_dirty(item)
        return True
    return False


@contextmanager
def set_dirty_context_manager(folder: str):
    set_dirty(folder)
    yield
    clean_dirty(folder)


@contextmanager
def chdir(newdir: str):
    old_path = os.getcwd()
    os.chdir(newdir)
    try:
        yield
    finally:
        os.chdir(old_path)


def sha256sum(file_path: str) -> str:
    with open(file_path, "rb") as fh:
        digest = hashlib.sha256()
        while True:
            data = fh.read(8192)
            if not data:
                break
            digest.update(data)
        return digest.hexdigest()


def check_sha256sum(file_path: str, provided_hash: str):
    real_hash = sha256sum(file_path)
    if real_hash != provided_hash.lower():
        raise RecipeException(
            "sha256 hash failed for '%s' file. \n"
            " Provided hash: %s  \n"
            " Computed hash: %s" % (os.path.basename(file_path), provided_hash, real_hash))


def save(path: str, content: str, encoding: str = "utf-8"):
    """
    Saves a file with given content
    Params:
        path: path to write file to
        content: contents to save in the file
        encoding: target file text encoding
    """

    dir_path = os.path.dirname(path)
    if dir_path:
        os.makedirs(dir_path, exist_ok=True)
    with open(path, "w", encoding=encoding, newline="") as handle:
        handle.write(content)


def save_files(path: str, files: Any, encoding: str = "utf-8"):
    for name, content in files.items():
        save(os.path.join(path, name), content, encoding=encoding)


def load(path: str, encoding: str = "utf-8") -> str:
    """ Loads a file content """
    with open(path, "r", encoding=encoding, newline="") as handle:
        tmp = handle.read()
    return tmp


def update_file(file_path: str, new_content: str):
    """Update a generated file only if it still carries the Recipe marker."""
    if not os.path.exists(file_path):
        save(file_path, new_content)
        return

    # content = load(file_path)
    # first_line = content.lstrip().split("\n", 1)[0]
    # if GENERATED_FILE_COMMENT in first_line and content != new_content:
    save(file_path, new_content)


def load_user_encoded(path: str) -> str:
    """ Exclusive for user side read-only files:
     - recipe.txt
     - profile files
     """
    with open(path, "rb") as handle:
        text = handle.read()

    import codecs
    encodings = {
        codecs.BOM_UTF8: "utf_8_sig",
        codecs.BOM_UTF32_BE: "utf_32_be",
        codecs.BOM_UTF32_LE: "utf_32_le",
        codecs.BOM_UTF16_BE: "utf_16_be",
        codecs.BOM_UTF16_LE: "utf_16_le",
        b"\x2b\x2f\x76\x38": "utf_7",
        b"\x2b\x2f\x76\x39": "utf_7",
        b"\x2b\x2f\x76\x2b": "utf_7",
        b"\x2b\x2f\x76\x2f": "utf_7",
        b"\x2b\x2f\x76\x38\x2d": "utf_7",
    }
    for bom, encoding in encodings.items():
        if text.startswith(bom):
            return text[len(bom):].decode(encoding)

    for decoder in ["utf-8", "Windows-1252"]:
        try:
            return text.decode(decoder)
        except UnicodeDecodeError:
            continue
    raise Exception(f"Unknown encoding of file: {path}\nIt is recommended to use utf-8 encoding")


def _change_permissions(func: Any, path: str, exc_info: Any):
    # rmtree failed to remove `path`. Usually it is read-only; on Windows it can also be a
    # System/Hidden file that blocks deletion - notably msys2's sys-format /etc/mtab symlink
    # (a System-attributed file), which is recreated every time bash runs. Clear the blocking
    # bits (chmod + Windows attributes) and retry the operation; if it still fails, let it raise.
    try:
        os.chmod(path, stat.S_IWUSR)
    except OSError:
        pass
    if platform.system() == "Windows":
        try:
            import ctypes
            # FILE_ATTRIBUTE_NORMAL clears ReadOnly/System/Hidden in one call.
            ctypes.windll.kernel32.SetFileAttributesW(str(path), 0x80)
        except Exception:
            pass
    func(path)


if platform.system() == "Windows":
    def rmdir(path: str | os.PathLike[str]):
        if not os.path.isdir(path):
            return

        retries = 3
        delay = 0.5
        for i in range(retries):
            try:
                shutil.rmtree(path, onerror=_change_permissions)  # pyright: ignore[reportDeprecated]  # onexc needs different signature; keep onerror for compat
                break
            except OSError as err:
                if i == retries - 1:
                    raise RecipeException(
                        f"Couldn't remove folder: {path}\n{str(err)}\n"
                        "Folder might be busy or open. "
                        "Close any app using it and retry.")
                time.sleep(delay)


    def renamedir(old_path: str, new_path: str):
        retries = 3
        delay = 0.5
        for i in range(retries):
            try:
                shutil.move(old_path, new_path)
                break
            except OSError as err:
                if i == retries - 1:
                    raise RecipeException(
                        f"Couldn't move folder: {old_path}->{new_path}\n"
                        f"{str(err)}\n"
                        "Folder might be busy or open. "
                        "Close any app using it and retry.")
                time.sleep(delay)
else:
    def rmdir(path: str | os.PathLike[str]):
        if not os.path.isdir(path):
            return
        try:
            shutil.rmtree(path, onerror=_change_permissions)  # pyright: ignore[reportDeprecated]  # onexc needs different signature; keep onerror for compat
        except OSError as err:
            raise RecipeException(
                f"Couldn't remove folder: {path}\n{str(err)}\n"
                "Folder might be busy or open. "
                "Close any app using it and retry.")


    def renamedir(old_path: str, new_path: str):
        try:
            shutil.move(old_path, new_path)
        except OSError as err:
            raise RecipeException(
                f"Couldn't move folder: {old_path}->{new_path}\n{str(err)}\n"
                "Folder might be busy or open. "
                "Close any app using it and retry.")


def remove(path: str):
    try:
        assert os.path.isfile(path)
        os.remove(path)
    except (IOError, OSError) as e:  # for py3, handle just PermissionError
        if e.errno == errno.EPERM or e.errno == errno.EACCES:
            os.chmod(path, stat.S_IRWXU)
            os.remove(path)
            return
        raise


def mkdir(path: str):
    """Recursive mkdir, doesnt fail if already existing"""
    if os.path.exists(path):
        return
    os.makedirs(path)


def tar_extract(fileobj: Any, destination_dir: str):
    the_tar = tarfile.open(fileobj=fileobj)
    # NOTE: The errorlevel=2 has been removed because it was failing in Win10, it didn't allow to
    # "could not change modification time", with time=0
    # the_tar.errorlevel = 2  # raise exception if any error
    the_tar.extraction_filter = (lambda member, path: member)  # fully_trusted, avoid Py3.14 break
    the_tar.extractall(path=destination_dir)
    the_tar.close()


def merge_directories(src: str, dst: str):
    from thirdparty.files import copy
    copy(None, pattern="*", src=src, dst=dst)  # pyright: ignore[reportArgumentType]  # copy ignores recipe for plain pattern copy


def gather_files(folder: str) -> tuple[dict[str, str], dict[str, str]]:
    file_dict: dict[str, str] = {}
    symlinked_folders: dict[str, str] = {}
    for root, dirs, files in os.walk(folder):
        if root != folder and not dirs and not files:  # empty folder
            rel_path = root[len(folder) + 1:].replace("\\", "/")
            symlinked_folders[rel_path] = root
            continue
        for d in dirs:
            abs_path = os.path.join(root, d)
            if os.path.islink(abs_path):
                rel_path = abs_path[len(folder) + 1:].replace("\\", "/")
                symlinked_folders[rel_path] = abs_path
        for f in files:
            if f == ".DS_Store":
                continue
            abs_path = os.path.join(root, f)
            rel_path = abs_path[len(folder) + 1:].replace("\\", "/")
            file_dict[rel_path] = abs_path

    return file_dict, symlinked_folders


def human_size(size_bytes: int) -> str:
    """
    format a size in bytes into a 'human' file size, e.g. B, KB, MB, GB, TB, PB
    Note that bytes will be reported in whole numbers but KB and above will have
    greater precision.  e.g. 43 B, 443 KB, 4.3 MB, 4.43 GB, etc
    """
    unit_size = 1000.0
    suffixes_table = [("B", 0), ("KB", 1), ("MB", 1), ("GB", 2), ("TB", 2), ("PB", 2)]

    num = float(size_bytes)
    the_precision = None
    the_suffix = None
    for suffix, precision in suffixes_table:
        the_precision = precision
        the_suffix = suffix
        if num < unit_size:
            break
        num /= unit_size

    if the_precision == 0:
        formatted_size = "%d" % num
    else:
        formatted_size = str(round(num, ndigits=the_precision))

    return "%s%s" % (formatted_size, the_suffix)


# FIXME: completely remove disutils once we don't support <3.8 any more
def copytree_compat(source_folder: str, dest_folder: str):
    if sys.version_info >= (3, 8):
        shutil.copytree(source_folder, dest_folder, dirs_exist_ok=True)
    else:
        from distutils.dir_util import copy_tree
        copy_tree(source_folder, dest_folder)
